wire[ADDR_LINE-1:0] addr = addra[ADDR_LINE-1:0];
wire is_uart = addra == SIM_UART_ADDR;
// mem_u_b_h_w[1]=1 means word, mem_u_b_h_w[0]=1 means halfword, otherwise byte.
wire word_op = mem_u_b_h_w[1];
wire half_op = mem_u_b_h_w[0];
// mem_u_b_h_w[2]=1 means unsigned (zero-extend), otherwise sign-extend.
wire sign_ext = ~mem_u_b_h_w[2];

// Byte-addressable write logic (UART writes excluded, they only produce
// simulation output). Written on the negative edge so store data latched
// at the positive edge is stable.
always @(negedge clka) begin
    if (wea && !is_uart) begin
        data[addr] <= dina[7:0];
        if (half_op | word_op) begin
            data[addr + 1] <= dina[15:8];
            if (word_op) begin
                data[addr + 2] <= dina[23:16];
                data[addr + 3] <= dina[31:24];
            end
        end
    end
end

// Byte-addressable read logic with sign/zero extension (little endian).
wire[7:0] b0 = data[addr];
wire[7:0] b1 = data[addr + 1];
wire[7:0] b2 = data[addr + 2];
wire[7:0] b3 = data[addr + 3];
wire[31:0] word_r = {b3, b2, b1, b0};
wire[31:0] half_r = {{16{sign_ext & b1[7]}}, b1, b0};
wire[31:0] byte_r = {{24{sign_ext & b0[7]}}, b0};

assign douta = is_uart ? 32'b0 :
               word_op ? word_r :
               half_op ? half_r :
               byte_r;

// UART simulation output: a write to SIM_UART_ADDR emits dina[7:0] as a
// character; valid pulses for one cycle per write.
reg[7:0] uart_char;
reg uart_valid;

initial begin
    uart_char = 8'b0;
    uart_valid = 1'b0;
end

always @(negedge clka) begin
    if (wea && is_uart) begin
        uart_char <= dina[7:0];
        uart_valid <= 1'b1;
    end
    else
        uart_valid <= 1'b0;
end

assign sim_uart_char_out = uart_char;
assign sim_uart_char_valid = uart_valid;

