always@(posedge clk) begin
    if (~cmu_stall) begin
        hazard_optype_MEM <= hazard_optype_EXE & {2{~reg_EM_flush}};
        hazard_optype_EXE <= hazard_optype_ID & {2{~reg_DE_flush}};
    end
end

parameter hazard_optype_ALU = 2'd1;
parameter hazard_optype_LOAD = 2'd2;
parameter hazard_optype_STORE = 2'd3;

// forwarding conditions for the ID-stage operand muxes
wire rs1_forward_EXE = rs1use_ID && (hazard_optype_EXE == hazard_optype_ALU) &&
    (rd_EXE != 0) && (rs1_ID == rd_EXE);
wire rs1_forward_MEM = rs1use_ID && (hazard_optype_MEM == hazard_optype_ALU) &&
    (rd_MEM != 0) && (rs1_ID == rd_MEM);
wire rs1_forward_LOAD = rs1use_ID && (hazard_optype_MEM == hazard_optype_LOAD) &&
    (rd_MEM != 0) && (rs1_ID == rd_MEM);

wire rs2_forward_EXE = rs2use_ID && (hazard_optype_EXE == hazard_optype_ALU) &&
    (rd_EXE != 0) && (rs2_ID == rd_EXE);
wire rs2_forward_MEM = rs2use_ID && (hazard_optype_MEM == hazard_optype_ALU) &&
    (rd_MEM != 0) && (rs2_ID == rd_MEM);
wire rs2_forward_LOAD = rs2use_ID && (hazard_optype_MEM == hazard_optype_LOAD) &&
    (rd_MEM != 0) && (rs2_ID == rd_MEM);

// load-use hazard: consumer in ID must wait one cycle for the load in EXE
wire load_stall = (hazard_optype_EXE == hazard_optype_LOAD) && (rd_EXE != 0) &&
    ((rs1use_ID && (rs1_ID == rd_EXE)) || (rs2use_ID && (rs2_ID == rd_EXE)));

