assign forward_ctrl_B = rs2_forward_EXE  ? 2'b01 :
                        rs2_forward_MEM  ? 2'b10 :
                        rs2_forward_LOAD ? 2'b11 :
                        2'b00;

// store data in EXE forwarded from an ALU result in MEM
