args.new_string:
reg[1:0] hazard_optype_EXE, hazard_optype_MEM;

// Track the producer type of the instructions in the EXE and MEM stages.
// A flushed (bubble) ID stage contributes "no hazard" to the EXE slot.
always@(posedge clk) begin
    hazard_optype_MEM <= hazard_optype_EXE;
    hazard_optype_EXE <= hazard_optype_ID & {2{~reg_DE_flush}};
end

localparam hazard_optype_ALU = 2'd1;
localparam hazard_optype_LOAD = 2'd2;
localparam hazard_optype_STORE = 2'd3;

// Load-use hazard: the consumer is in ID while the producing load is
// still in EXE — its data is not available until the MEM stage, so the
// pipeline stalls for one cycle and a bubble is inserted into EXE.
wire load_use = (hazard_optype_EXE == hazard_optype_LOAD) && (rd_EXE != 5'b0) &&
    ((rs1use_ID && (rs1_ID == rd_EXE)) ||
     (rs2use_ID && (rs2_ID == rd_EXE)));

assign PC_EN_IF = ~load_use;
assign reg_FD_stall = load_use;
assign reg_DE_flush = load_use;

// Branch taken in ID: the instruction fetched from the fall-through path
// is wrong, flush the IF/ID register.
assign reg_FD_flush = Branch_ID;

// Forwarding into the ID stage:
//   00 = register file, 01 = EXE-stage ALU result,
//   10 = MEM-stage ALU result, 11 = MEM-stage load data.
// A younger producer (EXE) has priority over an older one (MEM).
wire fwA_EXE = rs1use_ID && (hazard_optype_EXE == hazard_optype_ALU) &&
    (rd_EXE != 5'b0) && (rd_EXE == rs1_ID);
wire fwB_EXE = rs2use_ID && (hazard_optype_EXE == hazard_optype_ALU) &&
    (rd_EXE != 5'b0) && (rd_EXE == rs2_ID);
wire fwA_MEM_alu = rs1use_ID && (hazard_optype_MEM == hazard_optype_ALU) &&
    (rd_MEM != 5'b0) && (rd_MEM == rs1_ID);
wire fwB_MEM_alu = rs2use_ID && (hazard_optype_MEM == hazard_optype_ALU) &&
    (rd_MEM != 5'b0) && (rd_MEM == rs2_ID);
wire fwA_MEM_load = rs1use_ID && (hazard_optype_MEM == hazard_optype_LOAD) &&
    (rd_MEM != 5'b0) && (rd_MEM == rs1_ID);
wire fwB_MEM_load = rs2use_ID && (hazard_optype_MEM == hazard_optype_LOAD) &&
    (rd_MEM != 5'b0) && (rd_MEM == rs2_ID);

assign forward_ctrl_A = fwA_EXE ? 2'b01 :
                        fwA_MEM_alu ? 2'b10 :
                        fwA_MEM_load ? 2'b11 :
                        2'b00;
assign forward_ctrl_B = fwB_EXE ? 2'b01 :
                        fwB_MEM_alu ? 2'b10 :
                        fwB_MEM_load ? 2'b11 :
                        2'b00;

// Load-store forwarding: a store in EXE whose source register is the
// destination of a load in MEM takes the loaded data as its store data.
assign forward_ctrl_ls = (hazard_optype_EXE == hazard_optype_STORE) &&
    (hazard_optype_MEM == hazard_optype_LOAD) &&
    (rd_MEM != 5'b0) && (rs2_EXE == rd_MEM);

