		.Qk(rs_num_B),
		.Vj(rs1_data_RO),
		.Vk(rs2_data_RO),
		.A(32'b0),
		.pc_IS(PC_IS),

		.en_FU(FU_div_EN),
	    .vj(DIV_src1),
	    .vk(DIV_src2),
		.op_out(/* unused */),
