		.cdb_rs_rd(DIV_rs_rd),
		.cdb_rs_num(cdb_rs_num),
		.cdb_data(cdb_data),


		.pc_debug(/* unused */)
    );

    RS #(.FU(`FU_JUMP), .num(1)) rs_jump(
        .clk(debug_clk),
	    .rst(rst),

		.selected(issue_ok & JUMP_use),
	    .free_rs(rs_num_rd_JUMP),
	    .op(op_IS),
		.Qj(rs_num_A),
		.Qk(rs_num_B),
		.Vj(rs1_data_RO),
		.Vk(rs2_data_RO),
		.A(Imm_out_IS),
