    RS #(.FU(`FU_MEM), .num(1)) rs_mem(
        .clk(debug_clk),
	    .rst(rst),

		.selected(issue_ok & MEM_use),
	    .free_rs(rs_num_rd_MEM),
	    .op(op_IS),
		.Qj(rs_num_A),
		.Qk(rs_num_B),
		.Vj(rs1_data_RO),
		.Vk(rs2_data_RO),
