	    .rst(rst),

		.selected(issue_ok & JUMP_use),
	    .free_rs(rs_num_rd_JUMP),
	    .op(op_IS),
		.Qj(rs_num_A),
		.Qk(rs_num_B),
		.Vj(rs1_data_RO),
		.Vk(rs2_data_RO),
		.A(Imm_out_IS),
