        $display("x5 =%h (exp 0000F0F0)", core.register.register[5]);
        $display("x6 =%h (exp 00000000)", core.register.register[6]);
        $display("x7 =%h (exp 00000000)", core.register.register[7]);
        $display("x8 =%h (exp 00000000)", core.register.register[8]);
        $display("x16=%h (exp 000000ED)", core.register.register[16]);
        $display("ram[0]=%h (exp 0000801C, sb written back)", core.RAM.data[0]);
        $display("ram[1]=%h (exp 0000E71C, sh written back)", core.RAM.data[1]);
        $display("ram[2]=%h (exp ABCDE71C, sw written back)", core.RAM.data[2]);
        // X check on architectural state
        if (^core.register.register[1] === 1'bx || ^core.register.register[16] === 1'bx)
            $display("X PROPAGATION DETECTED");
        if (core.register.register[1]  === 32'hABCDE71C &&
            core.register.register[2]  === 32'hFFFFF0F0 &&
            core.register.register[3]  === 32'hF0F0F0F0 &&
            core.register.register[4]  === 32'h000000F0 &&
            core.register.register[5]  === 32'h0000F0F0 &&
            core.register.register[6]  === 32'h0 &&
            core.register.register[7]  === 32'h0 &&
            core.register.register[8]  === 32'h0 &&
            core.register.register[16] === 32'hED &&
            core.RAM.data[0] === 32'h0000801C &&
            core.RAM.data[1] === 32'h0000E71C &&
            core.RAM.data[2] === 32'hABCDE71C)
            $display("CORE TEST PASS");
        else
            $display("CORE TEST FAIL");
        $finish;
    end
    always #5 clk = ~clk;
endmodule
