// detect data hazards, generate forwarding controls, stall and flush signals
// forward_ctrl_A/B: 00 = register file, 01 = EXE bypass (ALUout_EXE),
//                   10 = MEM bypass (ALUout_MEM), 11 = MEM load/CSR data (Datain_MEM)
wire rs1_fwd_EXE = rs1use_ID & (rd_EXE != 5'b0) & (rd_EXE == rs1_ID) &
                   (hazard_optype_EXE == hazard_optype_ALU);
wire rs1_fwd_MEM_alu = rs1use_ID & (rd_MEM != 5'b0) & (rd_MEM == rs1_ID) &
                       (hazard_optype_MEM == hazard_optype_ALU);
wire rs1_fwd_MEM_load = rs1use_ID & (rd_MEM != 5'b0) & (rd_MEM == rs1_ID) &
                        (hazard_optype_MEM == hazard_optype_LOAD);

wire rs2_fwd_EXE = rs2use_ID & (rd_EXE != 5'b0) & (rd_EXE == rs2_ID) &
                   (hazard_optype_EXE == hazard_optype_ALU);
wire rs2_fwd_MEM_alu = rs2use_ID & (rd_MEM != 5'b0) & (rd_MEM == rs2_ID) &
                       (hazard_optype_MEM == hazard_optype_ALU);
wire rs2_fwd_MEM_load = rs2use_ID & (rd_MEM != 5'b0) & (rd_MEM == rs2_ID) &
                        (hazard_optype_MEM == hazard_optype_LOAD);

