                        rs2_fwd_MEM_alu  ? 2'b10 :
                        rs2_fwd_MEM_load ? 2'b11 : 2'b00;

// load-use hazard: load/CSR in EXE, consumer stalled one cycle in ID
wire load_use = (hazard_optype_EXE == hazard_optype_LOAD) & (rd_EXE != 5'b0) &
                ((rs1use_ID & (rd_EXE == rs1_ID)) | (rs2use_ID & (rd_EXE == rs2_ID)));

